(async () => {
  const nav = document.querySelector('#mobile-nav');
  const burger = document.querySelector('#burger');
  if (!nav || !burger) return {error: 'missing elements'};
  const before = {hidden: nav.hidden, cls: nav.className, expanded: burger.getAttribute('aria-expanded')};
  burger.click();
  await new Promise(r => setTimeout(r, 400));
  const after = {hidden: nav.hidden, cls: nav.className, expanded: burger.getAttribute('aria-expanded'),
                 display: getComputedStyle(nav).display, visible: nav.getBoundingClientRect().height};
  return {before, after};
})()
